require"active_support/notifications";module ActiveSupport;class DeprecationException<StandardError;end;class Deprecation;DEFAULT_BEHAVIORS={raise:->(message,callstack,deprecator) do e=DeprecationException.new(message);e.set_backtrace(callstack.map(&:to_s));raise e;end,stderr:->(message,callstack,deprecator) do $stderr.puts(message);$stderr.puts callstack.join("\n  ") if deprecator.debug;end,log:->(message,callstack,deprecator) do logger=if defined?(Rails.logger)&&Rails.logger;Rails.logger;else require"active_support/logger";ActiveSupport::Logger.new($stderr);end;logger.warn message;logger.debug callstack.join("\n  ") if deprecator.debug;end,notify:->(message,callstack,deprecator) do ActiveSupport::Notifications.instrument("deprecation.#{deprecator.gem_name.underscore.tr("/","_")}",message:message,callstack:callstack,gem_name:deprecator.gem_name,deprecation_horizon:deprecator.deprecation_horizon,);end,silence:->(message,callstack,deprecator){},report:->(message,callstack,deprecator) do error=DeprecationException.new(message);error.set_backtrace(callstack.map(&:to_s));ActiveSupport.error_reporter.report(error);end};module Behavior;attr_accessor:debug;def behavior;@behavior||=[DEFAULT_BEHAVIORS[:stderr]];end;def disallowed_behavior;@disallowed_behavior||=[DEFAULT_BEHAVIORS[:raise]];end;def behavior=(behavior)@behavior=Array(behavior).map{|b|DEFAULT_BEHAVIORS[b]||arity_coerce(b)};end;def disallowed_behavior=(behavior)@disallowed_behavior=Array(behavior).map{|b|DEFAULT_BEHAVIORS[b]||arity_coerce(b)};end;private;def arity_coerce(behavior)unless behavior.respond_to?(:call);raise ArgumentError,"#{behavior.inspect} is not a valid deprecation behavior.";end;case arity_of_callable(behavior);when 2;->(message,callstack,deprecator) do behavior.call(message,callstack);end;when -2..3;behavior;else ->(message,callstack,deprecator) do behavior.call(message,callstack,deprecator.deprecation_horizon,deprecator.gem_name);end;end;end;def arity_of_callable(callable)callable.respond_to?(:arity) ? callable.arity: callable.method(:call).arity;end;end;end;end
